function M.map_gen_settings()
  return {
    seed = 1,
    width = M.WIDTH,
    height = M.HEIGHT,
    starting_points = { M.SPAWN },
    no_enemies_mode = true,
    peaceful_mode = true,
    default_enable_all_autoplace_controls = false,
    autoplace_controls = {},
    autoplace_settings = {
      tile = { treat_missing_as_default = false, settings = { ["grass-1"] = { frequency = 1, size = 1, richness = 1 } } },
      entity = { treat_missing_as_default = false, settings = {} },
      decorative = { treat_missing_as_default = false, settings = {} },
    },
    cliff_settings = { name = "cliff", cliff_elevation_0 = 1024, cliff_elevation_interval = 10, richness = 0 },
  }
end

local function circle(cx, cy, r, fn)
  for x = math.floor(cx - r), math.ceil(cx + r) do
    for y = math.floor(cy - r), math.ceil(cy + r) do
      local d = math.sqrt((x + 0.5 - cx) ^ 2 + (y + 0.5 - cy) ^ 2)
      if d <= r then fn(x, y, d) end
    end
  end
end

-- Called once per lake whose area is taken by something the player built (extended map).
local on_lake_blocked = nil
---@param fn fun(surface: LuaSurface, position: MapPosition)
function M.on_lake_blocked(fn) on_lake_blocked = fn end

--- Key of a layout spot in storage.tt_map_blocked: surface, name and position, since several
--- cities share a name (2.6.1). The surface name comes first, up to the first "/".
---@param surface LuaSurface
local function blocked_key(surface, name, x, y)
  return surface.name .. "/" .. name .. "@" .. x .. "," .. y
end
M.blocked_key = blocked_key

--- Place every lake that is missing. On a new map nothing is in the way. On an extended map a
--- lake goes in only if no player entity stands in its area; otherwise it is reported once
--- and retried, like a blocked city.
---@param surface LuaSurface
local function place_lakes(surface)
  storage.tt_map_blocked = storage.tt_map_blocked or {}
  for _, lake in ipairs(M.LAKES) do
    local key = blocked_key(surface, "lake", lake.x, lake.y)
    if surface.get_tile(lake.x, lake.y).name ~= "deepwater" then
      local r = lake.radius + 1
      local area = { { lake.x - r, lake.y - r }, { lake.x + r, lake.y + r } }
      if surface.count_entities_filtered({ area = area, force = "player" }) == 0 then
        local tiles = {}
        circle(lake.x, lake.y, lake.radius, function(x, y, d)
          tiles[#tiles + 1] = { name = d < lake.radius * 0.6 and "deepwater" or "water", position = { x, y } }
        end)
        surface.set_tiles(tiles)
        storage.tt_map_blocked[key] = nil
      elseif not storage.tt_map_blocked[key] then
        storage.tt_map_blocked[key] = true
        if on_lake_blocked then on_lake_blocked(surface, { x = lake.x, y = lake.y }) end
      end
    else
      storage.tt_map_blocked[key] = nil
    end
  end
end

---@param surface LuaSurface
local function place_patches(surface)
  for _, p in ipairs(M.PATCHES) do
    local present = surface.count_entities_filtered({ name = p.name, position = { p.x + 0.5, p.y + 0.5 }, radius = p.radius }) > 0
    if present then
      -- already there
    elseif p.wells then
      for _, w in ipairs(p.wells) do
        surface.create_entity({ name = p.name, position = { p.x + w[1] + 0.5, p.y + w[2] + 0.5 }, amount = p.amount })
      end
    else
      circle(p.x, p.y, p.radius, function(x, y, d)
        local amount = math.floor(p.amount * (1 - 0.5 * d / p.radius))
        surface.create_entity({ name = p.name, position = { x + 0.5, y + 0.5 }, amount = amount })
      end)
    end
  end
end

-- Called once per city whose spot is blocked on an extended map (message to the player).
local on_city_blocked = nil
---@param fn fun(label: string, surface: LuaSurface, position: MapPosition)
function M.on_city_blocked(fn) on_city_blocked = fn end

--- Is any tier of this layout city standing at its spot?
---@param surface LuaSurface
local function city_present(surface, c)
  for _, e in pairs(surface.find_entities_filtered({ position = { c.x + 0.5, c.y + 0.5 }, radius = 1 })) do
    if cities.is_city(e) then return true end
  end
  return false
end

--- Place every layout city that is missing. Never removes anything: a blocked spot is
--- reported once and retried (storage.tt_map_blocked) until it is clear.
---@param surface LuaSurface
local function place_cities(surface)
  storage.tt_map_blocked = storage.tt_map_blocked or {}
  -- keys before 2.6.1 had no position ("surface/name"); place_cities re-records any still blocked
  for key in pairs(storage.tt_map_blocked) do
    if not string.find(key, "@", 1, true) then storage.tt_map_blocked[key] = nil end
  end
  for _, c in ipairs(M.CITIES) do
    if not city_present(surface, c) then
      local pos = { c.x + 0.5, c.y + 0.5 }
      local key = blocked_key(surface, c.name, c.x, c.y)
      -- 2.15: a city stands on a plot; paint it only where nothing of the player's is
      if plots.free(surface, pos) then plots.paint(surface, pos) end
      if surface.can_place_entity({ name = c.name, position = cities.snap(c.name, pos), force = "player" }) then
        cities.place(c.name, surface, pos, "player")
        storage.tt_map_blocked[key] = nil
      elseif not storage.tt_map_blocked[key] then
        storage.tt_map_blocked[key] = true
        if on_city_blocked then on_city_blocked(c.label, surface, { x = pos[1], y = pos[2] }) end
      end
    end
  end
end

--- Put a labelled map tag on every city of the surface. Charting is asynchronous, so tags
--- that can't be placed yet are retried from tick_tags (storage.tt_map_tags_pending).
---@param surface LuaSurface
local function tag_cities(surface)
  storage.tt_map_tags_pending = storage.tt_map_tags_pending or {}
  storage.tt_map_tags_pending[surface.name] = true
end

--- Place pending city map tags (called every GOAL_TICK_INTERVAL). Returns tags placed.
function M.tick_tags()
  local pending = storage.tt_map_tags_pending
  if not pending then return 0 end
  local placed = 0
  for surface_name in pairs(pending) do
    local surface = game.get_surface(surface_name)
    if not surface then
      pending[surface_name] = nil
    else
      local force = game.forces["player"]
      local all = true
      for _, c in ipairs(M.CITIES) do
        local pos = { x = c.x + 0.5, y = c.y + 0.5 }
        if #force.find_chart_tags(surface, { { pos.x - 1, pos.y - 1 }, { pos.x + 1, pos.y + 1 } }) == 0 then
          local tag = force.add_chart_tag(surface, {
            position = pos,
            icon = { type = "item", name = c.tag_icon },
            text = c.label,
          })
          if tag then placed = placed + 1 else all = false end
        end
      end
      if all then pending[surface_name] = nil end
    end
  end
  return placed
end


--- Create (if needed) and populate the map surface. Returns the surface.
---@param name string? surface name (default M.SURFACE)
function M.generate(name)
  name = name or M.SURFACE
  local surface = game.get_surface(name)
  if surface then return surface end
  surface = game.create_surface(name, M.map_gen_settings())
  local chunk_radius = math.ceil(math.max(M.WIDTH, M.HEIGHT) / 2 / 32) + 1
  surface.request_to_generate_chunks({ 0, 0 }, chunk_radius)
  surface.force_generate_chunk_requests()
  place_lakes(surface)
  place_patches(surface)
  place_cities(surface)
  game.forces["player"].chart(surface, { { -M.WIDTH / 2, -M.HEIGHT / 2 }, { M.WIDTH / 2, M.HEIGHT / 2 } })
  tag_cities(surface)
  return surface
end

--- Grow an existing map surface to the current layout (2.1 saves: 640 x 400 -> 960 x 600)
--- and add what it lacks: out-of-map tiles inside the new bounds become grass, missing
--- patches and cities are placed (blocked city spots are reported and retried), new cities
--- get tags. Idempotent.
---@param surface LuaSurface
function M.extend(surface)
  local mgs = surface.map_gen_settings
  if (mgs.width or 0) < M.WIDTH or (mgs.height or 0) < M.HEIGHT then
    mgs.width, mgs.height = M.WIDTH, M.HEIGHT
    surface.map_gen_settings = mgs
  end
  local area = { { -M.WIDTH / 2, -M.HEIGHT / 2 }, { M.WIDTH / 2, M.HEIGHT / 2 } }
  local chunk_radius = math.ceil(math.max(M.WIDTH, M.HEIGHT) / 2 / 32) + 1
  surface.request_to_generate_chunks({ 0, 0 }, chunk_radius)
  surface.force_generate_chunk_requests()
  local tiles = {}
  for _, t in pairs(surface.find_tiles_filtered({ area = area, name = "out-of-map" })) do
    tiles[#tiles + 1] = { name = "grass-1", position = t.position }
  end
  if #tiles > 0 then surface.set_tiles(tiles) end
  place_lakes(surface)
  place_patches(surface)
  place_cities(surface)
  game.forces["player"].chart(surface, area)
  tag_cities(surface)
end

--- Retry blocked city spots (called every GOAL_TICK_INTERVAL); cheap when nothing waits.
function M.retry_blocked()
  if not (storage.tt_map_blocked and next(storage.tt_map_blocked)) then return end
  local surfaces = {}
  for key in pairs(storage.tt_map_blocked) do surfaces[string.match(key, "^(.*)/")] = true end
  for name in pairs(surfaces) do
    local surface = game.get_surface(name)
    if surface then place_lakes(surface); place_cities(surface); tag_cities(surface) else
      for key in pairs(storage.tt_map_blocked) do
        if string.match(key, "^(.*)/") == name then storage.tt_map_blocked[key] = nil end
      end
    end
  end
end

-- 2.8.3: a site may move up to sites.SEARCH from its planned spot; sites stay at least
-- this share of the spacing apart (1 since 2.8.12: the minimum is a hard floor).
M.MIN_APART = 1
M.CHART_AROUND = 24 -- tiles charted around each site at the start (2.8.5)
M.ALT_TURN = 15
M.ALT_OUT, M.ALT_OUT_STEPS = 1.15, 4 -- then further out from spawn, up to 4 times
M.ALT_SEARCH = 96 -- how far a fallback spot's site may move
M.TAG_ICON = { type = "item", name = "refined-hazard-concrete" } -- the plot's painted border

--- Map tag text of a site.
---@param site table
local function site_label(site)
  local n = site.plots
  local text = n == 1 and "City plot" or (n .. " city plots")
  return site.starter and ("Start: " .. text) or text
end

--- Place a procedural plot layout on a surface with real terrain (2.15.6; cities until
--- then, 2.8.3): plan the sites from the seed, move each to the nearest usable land, clear
--- it and paint its plots. The placed sites are kept in storage.tt_layout[surface name]
--- (for tags, 2.8.5). Returns the placed sites and the labels of any that found no land.
---@param surface LuaSurface
---@param seed integer
---@param spacing number
function M.place_procedural(surface, seed, spacing)
  local placed, missing = {}, {}
  local function apart() return spacing * M.MIN_APART end
  local function free(x, y)
    for _, t in ipairs(placed) do
      local need = apart()
      if (t.x - x) ^ 2 + (t.y - y) ^ 2 < need * need then return false end
    end
    return true
  end
  --- Near the planned spot, else the same distance from spawn turned around it in
  --- ALT_TURN steps (+15, -15, +30, ...); if every turn is blocked, a little further out.
  local function near_plan(c)
    local half = layout.site_half(c.plots)
    local site = sites.find(surface, c.x, c.y, placed, apart, nil, half)
    local function try_spot(x, y)
      if not free(x, y) then return nil end
      return sites.find(surface, x, y, placed, apart, M.ALT_SEARCH, half)
    end
    local scale = 1
    for _ = 0, M.ALT_OUT_STEPS do
      local turn = 0
      while not site and turn < 360 / M.ALT_TURN - 1 do
        turn = turn + 1
        local ang = math.rad(M.ALT_TURN * math.ceil(turn / 2) * (turn % 2 == 1 and 1 or -1))
        local ca, sa = math.cos(ang) * scale, math.sin(ang) * scale
        site = try_spot(math.floor(c.x * ca - c.y * sa), math.floor(c.x * sa + c.y * ca))
      end
      if site then break end
      scale = scale * M.ALT_OUT
      site = try_spot(math.floor(c.x * scale), math.floor(c.y * scale))
    end
    return site
  end
  for _, c in ipairs(layout.plan(seed, spacing)) do
    c.label = site_label(c)
    local site = near_plan(c)
    if site then
      sites.clear(surface, site.x, site.y, layout.site_half(c.plots))
      c.planned = { x = c.x, y = c.y }
      c.x, c.y = site.x, site.y
      for _, o in ipairs(layout.offsets(c.plots)) do
        plots.paint(surface, { c.x + o[1], c.y + o[2] }, true)
      end
      c.tag_icon = M.TAG_ICON.name
      placed[#placed + 1] = c
    else
      missing[#missing + 1] = c.label
    end
  end
  for _, label in ipairs(missing) do log("tracktorio: no land for " .. label) end
  storage.tt_layout = storage.tt_layout or {}
  storage.tt_layout[surface.name] = placed
  -- 2.8.5 (user, playtest 2.8.7): every site is on the map from the start. Chart a little
  -- around each one; on_chunk_charted then puts its tag on. The rest of the map stays dark.
  local force = game.forces["player"]
  for _, c in ipairs(placed) do
    force.chart(surface, { { c.x - M.CHART_AROUND, c.y - M.CHART_AROUND }, { c.x + M.CHART_AROUND, c.y + M.CHART_AROUND } })
  end
  return placed, missing
end

--- on_chunk_charted (2.8.5): on a procedural map a site's tag goes on when its chunk is
--- first charted. place_procedural charts every site at the start, so all tags show from
--- the start (user, playtest 2.8.7); this also tags a site for a force charting it later.
---@param e EventData.on_chunk_charted
function M.on_chunk_charted(e)
  local surface = game.get_surface(e.surface_index)
  if not surface then return end
  local placed = storage.tt_layout and storage.tt_layout[surface.name]
  if not placed then return end
  local lt, rb = e.area.left_top, e.area.right_bottom
  for _, c in ipairs(placed) do
    local x, y = c.x + 0.5, c.y + 0.5
    if not (c.tagged and c.tagged[e.force.index]) and x >= lt.x and x < rb.x and y >= lt.y and y < rb.y then
      local tag = e.force.add_chart_tag(surface, { position = { x = x, y = y },
        icon = { type = "item", name = c.auto_icon or c.tag_icon }, text = c.auto_text or c.label })
      if tag then
        c.tagged = c.tagged or {}
        c.tagged[e.force.index] = true
      end
    end
  end
end

